set -e
cd "$(dirname "$0")"
mkdir -p site strict
printf '%s\n' 'hello from surl' > site/hello.txt
printf '%s\n' 'hello from surl' > strict/hello.txt
surl --directory site --user app:s3cret-pw --allow-plaintext-auth http://localhost:8080/ ftp://localhost:8081/ &
surl socks5h://127.0.0.1:8082/ -v --log-file proxy.log &
sleep 1
curl -s -x socks5h://127.0.0.1:8082 -u app:s3cret-pw ftp://localhost:8081/hello.txt
kill $(jobs -p)
